<?php
// Public booking page: book.php?t=LEAD_TOKEN (personal link) or book.php?g=BOOKING_KEY (general link)
require __DIR__.'/app/bootstrap.php';
session_write_close();
$t=preg_replace('/[^a-f0-9]/','',$_GET['t']??'');$g=preg_replace('/[^a-f0-9]/','',$_GET['g']??'');
$lead=$t?DB::row('SELECT * FROM leads WHERE token=?',[$t]):null;
if(!$lead&&(!$g||!hash_equals(setting('booking_key'),$g))){http_response_code(404);exit('This booking link is not valid.');}
$err='';$done=null;$days=21;
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){
  try{
    $start=(int)($_POST['slot']??0);
    $ok=false;foreach(Booking::slots($days) as $day)if(in_array($start,$day,true))$ok=true;
    if(!$ok)throw new Exception('Please choose an available time.');
    if(!$lead){
      $name=trim($_POST['name']??'');$phone=trim($_POST['phone']??'');
      if($name===''||$phone==='')throw new Exception('Please enter your name and phone number.');
      $lid=CRM::create(['contact_name'=>$name,'name'=>trim($_POST['company']??'')?:$name,'phone'=>$phone,'email'=>trim($_POST['email']??''),'message'=>trim($_POST['notes']??'')],'booking','Booking page');}
    else $lid=$lead['id'];
    $aid=Booking::book($lid,$start,'lead',trim($_POST['notes']??''));
    $done=DB::row('SELECT * FROM appointments WHERE id=?',[$aid]);}
  catch(Throwable $e){$err=$e->getMessage();}}
$slots=$done?[]:Booking::slots($days);
// Readable text on brand colours
$lum=function($h){$h=ltrim($h,'#');if(strlen($h)===3)$h=preg_replace('/(.)/','$1$1',$h);[$r,$g2,$b]=array_map(fn($x)=>hexdec($x)/255,str_split(substr($h.'000000',0,6),2));$f=fn($c)=>$c<=.03928?$c/12.92:(($c+.055)/1.055)**2.4;return .2126*$f($r)+.7152*$f($g2)+.0722*$f($b);};
$P=setting('brand_primary','#0B0B0B');$A=setting('brand_accent','#B8860B');
if(!preg_match('/^#[0-9a-f]{3,6}$/i',$P))$P='#0B0B0B';if(!preg_match('/^#[0-9a-f]{3,6}$/i',$A))$A='#4F46E5';
$onP=$lum($P)>.45?'#111827':'#FFFFFF';$onA=$lum($A)>.45?'#111827':'#FFFFFF';$txA=$lum($A)>.45?'#111827':$A;
$len=(int)setting('appt_slot','30');$loc=setting('appt_location');$co=setting('company_name');
$gcalUrl=$done?'https://calendar.google.com/calendar/render?'.http_build_query(['action'=>'TEMPLATE','text'=>$done['title'],'dates'=>gmdate('Ymd\THis\Z',strtotime($done['start_at'])).'/'.gmdate('Ymd\THis\Z',strtotime($done['end_at'])),'details'=>'Booked with '.$co,'location'=>$done['location']]):'';
$part=fn($ts)=>(int)date('G',$ts)<12?'Morning':((int)date('G',$ts)<17?'Afternoon':'Evening');
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Book a time · <?=e($co)?></title><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Inter+Tight:wght@600;700&display=swap" rel="stylesheet"><style>
:root{--p:<?=e($P)?>;--onp:<?=$onP?>;--a:<?=e($A)?>;--ona:<?=$onA?>;--ta:<?=e($txA)?>;--ink:#111827;--txt:#374151;--mut:#6B7280;--line:#E5E7EB}
*{box-sizing:border-box}[hidden]{display:none!important}body{margin:0;font:15px/1.55 Inter,system-ui,sans-serif;background:#F3F4F8;color:var(--txt);-webkit-font-smoothing:antialiased}h1,h2,h3{font-family:'Inter Tight',Inter,sans-serif;color:var(--ink);margin:0;letter-spacing:-.01em}
.w{max-width:1040px;margin:32px auto;padding:0 16px}.bx{display:grid;grid-template-columns:330px 1fr;background:#fff;border-radius:22px;overflow:hidden;box-shadow:0 20px 60px rgba(17,24,39,.08);border:1px solid var(--line)}
.side{background:var(--p);color:var(--onp);padding:30px 28px;display:flex;flex-direction:column;gap:18px}.side img{max-height:58px;max-width:200px;object-fit:contain;align-self:flex-start}.side h1{color:var(--onp);font-size:24px;line-height:1.25}.side p{margin:0;opacity:.85}.side .it{display:flex;gap:10px;align-items:flex-start;font-size:14px}.side .it svg{flex:none;width:18px;height:18px;margin-top:2px;opacity:.85}.side .ft{margin-top:auto;font-size:12.5px;opacity:.7}
.main{padding:30px 32px}.st{display:flex;align-items:center;gap:10px;margin:0 0 14px}.st b{width:26px;height:26px;border-radius:50%;background:var(--a);color:var(--ona);display:flex;align-items:center;justify-content:center;font-size:13px}.st h2{font-size:17px}.blk+.blk{margin-top:26px}
.days{display:grid;grid-template-columns:repeat(auto-fill,minmax(74px,1fr));gap:8px}.day{border:1.5px solid var(--line);border-radius:14px;padding:9px 4px;text-align:center;cursor:pointer;background:#fff;color:var(--ink);font:inherit;transition:border-color .15s,background .15s}.day small{display:block;font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--mut);font-weight:600}.day strong{display:block;font-size:20px;line-height:1.2}.day em{display:block;font-style:normal;font-size:11px;color:var(--mut)}.day:hover{border-color:var(--a)}.day.on{background:var(--a);border-color:var(--a);color:var(--ona)}.day.on small,.day.on em{color:var(--ona);opacity:.85}
.grp{margin-top:6px}.grp h3{font-size:12px;text-transform:uppercase;letter-spacing:.08em;color:var(--mut);margin:14px 0 8px;font-family:Inter,sans-serif}.times{display:grid;grid-template-columns:repeat(auto-fill,minmax(104px,1fr));gap:8px}.times label{position:relative;cursor:pointer}.times input{position:absolute;opacity:0;pointer-events:none}.times span{display:block;border:1.5px solid var(--line);border-radius:11px;padding:10px 6px;text-align:center;font-weight:600;color:var(--ink);background:#fff;transition:all .15s}.times label:hover span{border-color:var(--a)}.times input:checked+span{background:var(--a);border-color:var(--a);color:var(--ona)}.times input:focus-visible+span{outline:3px solid color-mix(in srgb,var(--a) 35%,transparent)}
.f{display:grid;grid-template-columns:1fr 1fr;gap:12px}.f label{font-size:13px;font-weight:600;color:var(--ink)}.f input,.f textarea{display:block;width:100%;margin-top:6px;padding:12px 13px;border:1.5px solid var(--line);border-radius:11px;font:inherit;color:var(--ink);background:#fff;outline:0}.f input:focus,.f textarea:focus{border-color:var(--a);box-shadow:0 0 0 4px color-mix(in srgb,var(--a) 15%,transparent)}.f .full{grid-column:1/-1}
.sum{display:flex;align-items:center;gap:12px;margin-top:24px;padding:14px 16px;border-radius:14px;background:#F9FAFB;border:1px solid var(--line);flex-wrap:wrap}.sum span{flex:1;min-width:180px;color:var(--mut)}.sum strong{color:var(--ink)}button.go{padding:14px 26px;border:0;border-radius:12px;background:var(--a);color:var(--ona);font:600 15.5px Inter,sans-serif;cursor:pointer;box-shadow:0 8px 20px color-mix(in srgb,var(--a) 30%,transparent)}button.go:disabled{opacity:.45;cursor:not-allowed;box-shadow:none}
.err{background:#FEF2F2;border:1px solid #FECACA;color:#991B1B;padding:12px 14px;border-radius:12px;margin-bottom:18px}.ok{text-align:center;padding:24px 10px}.ok .ck{width:68px;height:68px;border-radius:50%;background:#DCFCE7;color:#15803D;display:flex;align-items:center;justify-content:center;margin:0 auto 14px}.ok h2{font-size:24px}.ok .when{font-size:17px;font-weight:600;color:var(--ink);margin:8px 0 4px}.ok a.btn{display:inline-flex;align-items:center;gap:8px;margin:16px 6px 0;padding:11px 18px;border-radius:11px;border:1.5px solid var(--line);color:var(--ink);font-weight:600;text-decoration:none}.ok a.btn.pri{background:var(--a);border-color:var(--a);color:var(--ona)}
.none{padding:30px;text-align:center;color:var(--mut);border:1.5px dashed var(--line);border-radius:14px}
@media(max-width:820px){.bx{grid-template-columns:1fr}.side{padding:24px}.main{padding:22px 18px}.f{grid-template-columns:1fr}.w{margin:16px auto}}
</style></head><body><div class="w"><div class="bx"><aside class="side"><?php [$lf,$chip]=Report::logoPick($P);if($lf):?><img src="<?=e(base_url($lf))?>" alt="<?=e($co)?>"<?=$chip?' style="background:'.$chip.';padding:8px 10px;border-radius:10px"':''?>><?php endif?><div><h1><?=e(setting('appt_title','Book a meeting'))?></h1><p style="margin-top:6px"><?=e($co)?></p></div><div class="it"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/></svg><span><?=$len?> minutes</span></div><?php if($loc):?><div class="it"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M20 10c0 6-8 12-8 12s-8-6-8-12a8 8 0 0 1 16 0Z"/><circle cx="12" cy="10" r="3"/></svg><span><?=e(preg_match('~^https?://~',$loc)?(stripos($loc,'meet.google')!==false?'Google Meet (link in confirmation)':'Online meeting (link in confirmation)'):$loc)?></span></div><?php elseif(GCal::ready()&&setting('gcal_meet','1')==='1'):?><div class="it"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><rect x="2" y="6" width="14" height="12" rx="2"/><path d="m22 8-6 4 6 4z"/></svg><span>Google Meet video call</span></div><?php endif?><?php if($lead):?><div class="it"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="12" cy="8" r="5"/><path d="M20 21a8 8 0 0 0-16 0"/></svg><span>For <?=e($lead['contact_name']?:$lead['name'])?></span></div><?php endif?><p class="ft">Times are shown in <?=e(date_default_timezone_get())?> time. You'll get a confirmation by email<?=WhatsApp::provider()!=='manual'?' and WhatsApp':''?>.</p></aside>
<main class="main"><?php if($done):?><div class="ok"><div class="ck"><svg width="34" height="34" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6 9 17l-5-5"/></svg></div><h2>You're booked!</h2><p class="when"><?=e(date('l, d F Y · h:i A',strtotime($done['start_at'])))?></p><p style="color:var(--mut)"><?=e($done['meet_link']?'A Google Meet link has been sent to your email.':'A confirmation has been sent. We look forward to speaking with you.')?></p><?php if($done['meet_link']):?><a class="btn pri" href="<?=e($done['meet_link'])?>" target="_blank" rel="noopener">Open Google Meet</a><?php endif?><a class="btn" href="<?=e($gcalUrl)?>" target="_blank" rel="noopener">Add to my calendar</a></div>
<?php else:?><form method="post" id="bf"><?php if($err):?><div class="err"><?=e($err)?></div><?php endif?><?php if(!$slots):?><div class="none">No free times in the next <?=$days?> days. Please call us on <b><?=e(setting('company_phone'))?></b>.</div><?php else:?>
<div class="blk"><div class="st"><b>1</b><h2>Pick a day</h2></div><div class="days"><?php $i=0;foreach($slots as $d=>$ts):$dt=strtotime($d);?><button type="button" class="day <?=$i===0?'on':''?>" data-d="<?=$d?>"><small><?=date('D',$dt)?></small><strong><?=date('d',$dt)?></strong><em><?=date("M",$dt)?></em></button><?php $i++;endforeach?></div></div>
<div class="blk"><div class="st"><b>2</b><h2>Pick a time</h2></div><?php $i=0;foreach($slots as $d=>$ts):$gr=[];foreach($ts as $s)$gr[$part($s)][]=$s;?><div class="grp" data-t="<?=$d?>" <?=$i?'hidden':''?>><?php foreach($gr as $gn=>$list):?><h3><?=$gn?></h3><div class="times"><?php foreach($list as $s):?><label><input type="radio" name="slot" value="<?=$s?>" data-l="<?=e(date('D, d M · h:i A',$s))?>" required><span><?=date('h:i A',$s)?></span></label><?php endforeach?></div><?php endforeach?></div><?php $i++;endforeach?></div>
<div class="blk"><div class="st"><b>3</b><h2><?=$lead?'Anything to add?':'Your details'?></h2></div><div class="f"><?php if(!$lead):?><label>Your name *<input name="name" required autocomplete="name"></label><label>Phone / WhatsApp *<input name="phone" type="tel" required autocomplete="tel"></label><label>Email<input name="email" type="email" autocomplete="email"></label><label>Business name<input name="company" autocomplete="organization"></label><?php endif?><label class="full">What would you like to discuss?<textarea name="notes" rows="3" placeholder="Optional"></textarea></label></div></div>
<div class="sum"><span id="sel">Choose a time to continue</span><button class="go" id="go" disabled>Confirm booking</button></div><?php endif?></form><?php endif?></main></div></div>
<script>(function(){var q=function(s){return document.querySelectorAll(s)};q('.day').forEach(function(d){d.onclick=function(){q('.day').forEach(function(x){x.classList.toggle('on',x===d)});q('.grp').forEach(function(g){g.hidden=g.dataset.t!==d.dataset.d})}});var go=document.getElementById('go'),sel=document.getElementById('sel');q('input[name=slot]').forEach(function(r){r.onchange=function(){go.disabled=false;sel.innerHTML='<strong>'+r.dataset.l+'</strong> · <?=$len?> min'}});var f=document.getElementById('bf');if(f)f.onsubmit=function(){go.disabled=true;go.textContent='Booking…'}})()</script></body></html>
<?php Cron::kick();
